def shiftset(s,t): return {(r+t[0],c+t[1]) for r,c in s}
base='4'
solutions=[]; nodes=0

def check_partial(T):
    # exact marker multiplicity <=2; no color/color or color/marker collisions
    col=defaultdict(list); mk=defaultdict(list)
    allxy=[]
    for k,t in T.items():
        for p in shiftset(cells2[k],t): col[p].append(k); allxy.append(p)
        for p in shiftset(marks2[k],t): mk[p].append(k); allxy.append(p)
    if any(len(v)>1 for v in col.values()): return False
    if any(p in col for p in mk): return False
    if any(len(v)>2 for v in mk.values()): return False
    if allxy:
        if max(r for r,c in allxy)-min(r for r,c in allxy)>=26 or max(c for r,c in allxy)-min(c for r,c in allxy)>=26: return False
    return True

def rec(T, remaining):
    global nodes
    nodes+=1
    if nodes>1000000: return
    if not remaining:
        mk=defaultdict(list)
        for k,t in T.items():
            for p in shiftset(marks2[k],t): mk[p].append(k)
        if mk and all(len(v)==2 for v in mk.values()):
            solutions.append(T.copy())
        return
    # candidate options for every remaining piece from marker alignments with placed pieces
    best=None
    for k in remaining:
        opts=set()
        for j,tj in T.items():
            for pk in marks2[k]:
                for pj in marks2[j]:
                    tt=(tj[0]+pj[0]-pk[0], tj[1]+pj[1]-pk[1])
                    opts.add(tt)
        good=[]
        for tt in opts:
            # new piece needs actual marker coincidence
            if not any((p[0]+tt[0],p[1]+tt[1]) in set().union(*(shiftset(marks2[j],tj) for j,tj in T.items())) for p in marks2[k]):
                continue
            T[k]=tt
            if check_partial(T): good.append(tt)
            del T[k]
        # choose fewest options to branch
        if best is None or len(good)<len(best[1]): best=(k,good)
    if best is None or not best[1]: return
    k,opts=best
    for tt in opts:
        T[k]=tt
        rec(T, [x for x in remaining if x!=k])
        del T[k]
        if len(solutions)>=100: return

