def rec2(T, remaining, forbid_cc=False, forbid_cm=False, require_pairs=True, cap=1000000):
    sols=[]; count=[0]
    def valid(T):
        cols=defaultdict(list);mks=defaultdict(list);allxy=[]
        for k,t in T.items():
            for p in shiftset(cells2[k],t):cols[p].append(k);allxy.append(p)
            for p in shiftset(marks2[k],t):mks[p].append(k);allxy.append(p)
        if forbid_cc and any(len(v)>1 for v in cols.values()):return False
        if forbid_cm and any(p in cols for p in mks):return False
        if any(len(v)>2 for v in mks.values()):return False
        if allxy and (max(r for r,c in allxy)-min(r for r,c in allxy)>=26 or max(c for r,c in allxy)-min(c for r,c in allxy)>=26):return False
        return True
    def search(T,rem):
        count[0]+=1
        if count[0]>cap:return
        if not rem:
            mk=defaultdict(list)
            for k,t in T.items():
                for p in shiftset(marks2[k],t):mk[p].append(k)
            if (not require_pairs or (mk and all(len(v)==2 for v in mk.values()))):sols.append(T.copy())
            return
        best=None
        for k in rem:
            opts=set()
            for j,tj in T.items():
                for pk in marks2[k]:
                    for pj in marks2[j]:opts.add((tj[0]+pj[0]-pk[0],tj[1]+pj[1]-pk[1]))
            good=[]
            for tt in opts:
                T[k]=tt
                if valid(T):good.append(tt)
                del T[k]
            if best is None or len(good)<len(best[1]):best=(k,good)
        if not best or not best[1]:return
        k,opts=best
        for tt in opts:
            T[k]=tt;search(T,[x for x in rem if x!=k]);del T[k]
            if len(sols)>=30:return
    search(T,remaining)
    return sols,count[0]
